const UNION_SKILL={Food:'Green',Luxury:'Blue',Health:'White',Education:'Orange',Media:'Purple'},skillColors={Green:'緑',Blue:'青',White:'白',Orange:'橙',Purple:'紫'};
function unionWorkerLabel(industry){const skill=UNION_SKILL[industry];return `${skills[skill]}の熟練労働者（${skillColors[skill]}）`;}
