const fields={
 Working:{cash:'資金',population:'人口',workerCount:'労働者の総数',prosperity:'繁栄度',loans:'貸付金',influence:'影響力',vp:'勝利点',billMarkers:'法案マーカー',food:'食料',health:'健康',education:'教育',luxury:'贅沢品'},
 Capitalist:{revenue:'収入',capital:'資本',wealth:'富',loans:'貸付金',influence:'影響力',vp:'勝利点',billMarkers:'法案マーカー',food:'食料在庫',health:'健康在庫',education:'教育在庫',luxury:'贅沢品在庫',freeTradeFood:'自由貿易区の食料',freeTradeLuxury:'自由貿易区のぜいたく品',foodStorage:'食料倉庫タイル',luxuryStorage:'ぜいたく品倉庫タイル',healthStorage:'健康倉庫タイル',educationStorage:'教育倉庫タイル',foodPrice:'食料単価',healthPrice:'健康単価',educationPrice:'教育単価',luxuryPrice:'贅沢品単価'},
 Middle:{prosperityStep:'繁栄度マーカーの位置（0〜10）',consumedFood:'購入済み食料',consumedHealth:'購入済み医療',consumedEducation:'購入済み教育',consumedLuxury:'購入済み贅沢品',foodPrice:'食料単価',healthPrice:'医療単価',educationPrice:'教育単価',luxuryPrice:'贅沢品単価',foodStorage:'食料倉庫タイル',healthStorage:'医療倉庫タイル',educationStorage:'教育倉庫タイル',luxuryStorage:'贅沢品倉庫タイル',cash:'資金',population:'人口',workerCount:'労働者の総数',prosperity:'繁栄度',loans:'貸付金',influence:'影響力',vp:'勝利点',billMarkers:'法案マーカー',food:'食料',health:'健康',education:'教育',luxury:'贅沢品'},
 State:{cash:'国庫',loans:'貸付金',influence:'個人影響力',vp:'勝利点',food:'食料',luxury:'贅沢品',foodPrice:'食料単価',luxuryPrice:'贅沢品単価',workingLegitimacy:'労働者からの正当性',middleLegitimacy:'中産階級からの正当性',capitalistLegitimacy:'資本家からの正当性'}
};
