const specialCompanies=root.WCA_EXTRA_COMPANIES;
const policyNames={1:'財政政策',2:'労働市場',3:'税制',4:'福祉国家：医療と給付',5:'福祉国家：教育',6:'外国貿易',7:'移民'};
