// Basic rules: Working Class actions (printed pp.15–17); no AI-card bonuses.
function applyWorkingBasic(records,plan,positions){
 const r=clone(records),w=r.personal.Working.values,unionSkill={Food:'Green',Luxury:'Blue',Health:'White',Education:'Orange',Media:'Purple'};
 check(r.participants.Working==='human'&&r.participants.Middle==='absent','労働者プレイヤーの2人用基本アクションに対応しています');
 check(plan&&['AW','BGS','STR','DEM','PRESSURE'].includes(plan.action),'基本アクションが不正です');
 if(plan.action==='AW'){
  const allocations=plan.allocations||[],unions=plan.unions||[],count=allocations.reduce((n,a)=>n+(a.skills||[]).length,0)+unions.length;
  check(count>0&&count<=3,'割り当てる労働者は1〜3人です');
  check(new Set(allocations.map(a=>a.companyId)).size===allocations.length&&new Set(unions).size===unions.length,'配置先が重複しています');
  const take=skill=>{check(Object.hasOwn(skills,skill)&&r.common.unemployed.Working[skill]>0,'失業労働者が足りません');r.common.unemployed.Working[skill]--;};
  for(const a of allocations){const c=r.companies[a.companyId],d=c&&effective(companyDef(a.companyId),c);check(c?.status==='built'&&c.slots.length>0&&c.slots.every(x=>x.owner==='empty'),'全スロットが空いている企業を選んでください');check(a.skills.length===c.slots.length,'企業の全スロットを同時に埋めてください');c.slots=a.skills.map((skill,i)=>{check(workerFits(d.workers[i],'Working',skill,d.class),'必要な技能と一致しません');take(skill);return {owner:'Working',skill,committed:true};});c.operating='yes';}
  for(const industry of unions){check(unionSkill[industry]&&!r.personal.Working.unions[industry],'この労働組合は設立できません');const employed=Object.entries(r.companies).reduce((n,[id,c])=>n+(c.status==='built'&&companyDef(id).industry===industry?c.slots.filter(x=>x.owner==='Working').length:0),0);check(employed>=4,'組合設立には同じ産業で働く労働者4人が必要です');take(unionSkill[industry]);r.personal.Working.unions[industry]=true;w.vp=Number(w.vp||0)+2;}
 }else if(plan.action==='BGS'){
  check(['food','health','education','luxury'].includes(plan.resource),'購入する資源が不正です');const purchases=plan.purchases||[];check(purchases.length>0&&new Set(purchases.map(p=>p.source)).size===purchases.length,'購入先を重複させないでください');let total=0,qty=0;
  for(const p of purchases){check(Number.isSafeInteger(p.qty)&&p.qty>0&&p.qty<=w.population,'各購入先から購入できる数量は人口までです');const key=plan.resource;let price;
   if(p.source==='Capitalist'){const cap=r.personal.Capitalist.values;check(cap[key]!=null&&cap[key+'Price']!=null&&cap[key]>=p.qty,'資本家の在庫・価格を確認してください');price=cap[key+'Price'];}
   else if(p.source==='State'){check(['health','education'].includes(key)&&r.common.values[key]!=null&&r.common.values[key]>=p.qty,'国家から購入できる在庫がありません');price=({A:0,B:5,C:10})[positions[key==='health'?4:5]];}
   else{check(p.source==='Foreign'&&['food','luxury'].includes(key),'この購入先では購入できません');price=key==='food'?({A:20,B:15,C:10})[positions[6]]:({A:12,B:9,C:6})[positions[6]];}
   total+=price*p.qty;qty+=p.qty;
   if(p.source==='Capitalist'){r.personal.Capitalist.values[key]-=p.qty;r.personal.Capitalist.values.revenue+=price*p.qty;}
   else if(p.source==='State'){r.common.values[key]-=p.qty;r.personal.State.values.cash+=price*p.qty;}
   else r.personal.State.values.cash+=(price-(key==='food'?10:6))*p.qty;
  }
  check(w.cash!=null&&w.cash>=total,'購入資金が足りません');w.cash-=total;w[plan.resource]=Number(w[plan.resource]||0)+qty;
 }else if(plan.action==='STR'){
  const ids=plan.companyIds||[];check(ids.length>=1&&ids.length<=2&&new Set(ids).size===ids.length,'ストライキは異なる企業1〜2社を選んでください');
  for(const id of ids){const c=r.companies[id],d=companyDef(id);check(c?.status==='built'&&c.slots.some(x=>x.owner==='Working')&&!c.slots.some(x=>x.committed)&&!c.strike&&['L1','L2'].includes(c.wage)&&(d.class!=='State'||r.participants.State==='human'),'ストライキできない企業です');c.strike=true;c.slots.filter(x=>x.owner==='Working').forEach(x=>x.committed=true);}
 }else if(plan.action==='DEM'){check(demonstrationStatus(r).eligible,'デモには空きスロットより2人以上多い失業労働者が必要です');check(!r.common.tokens.demonstration,'デモは既に実施中です');r.common.tokens.demonstration=true;}
 else {check(r.common.values.workingVotesOutside!=null,'投票駒を確認してください');r.common.values.workingVotesOutside=Math.max(0,r.common.values.workingVotesOutside-3);}
 return validate(r);
}
function startPreview(records){const w=records.personal.Working.values,cashBefore=Number(w.cash||0),loansBefore=Number(w.loans||0),repay=Math.min(loansBefore,Math.floor(cashBefore/50)),cost=repay*50;return {cashBefore,loansBefore,repay,cost,cashAfter:cashBefore-cost,loansAfter:loansBefore-repay,benefits:records.participants.State==='human'?'manual':'unavailable'};}
function applyStart(records){const r=clone(records),p=startPreview(r),w=r.personal.Working.values;w.cash=p.cashAfter;w.loans=p.loansAfter;return validate(r);}
function payCapitalist(values,amount,preferred='revenue'){let due=Number(amount);check(Number.isSafeInteger(due)&&due>=0,'支払額が不正です');while(Number(values.revenue||0)+Number(values.capital||0)<due){values.capital=Number(values.capital||0)+50;values.loans=Number(values.loans||0)+1;}const first=preferred==='capital'?'capital':'revenue',second=first==='capital'?'revenue':'capital',paid=Math.min(Number(values[first]||0),due);values[first]-=paid;due-=paid;values[second]=Number(values[second]||0)-due;}
function payCapitalOnly(values,amount){const due=Number(amount);check(Number.isSafeInteger(due)&&due>=0,'支払額が不正です');while(Number(values.capital||0)<due){values.capital=Number(values.capital||0)+50;values.loans=Number(values.loans||0)+1;}values.capital-=due;}
function applyCapitalistPurchase(records,plan,foreignPolicy){
 const r=clone(records),cap=r.personal.Capitalist.values,state=r.personal.State.values;check(plan&&['Foreign','BusinessDeal'].includes(plan.source),'購入先が不正です');let base=0,tariff=0,food=0,luxury=0,destination='regular';
 if(plan.source==='Foreign'){check(['food','luxury'].includes(plan.resource),'海外市場から購入できるのは食料とぜいたく品です');const qty=Number(plan.qty);check(Number.isSafeInteger(qty)&&qty>0,'購入数が不正です');const unit=plan.resource==='food'?10:6,tariffUnit=plan.resource==='food'?({A:10,B:5,C:0})[foreignPolicy]:({A:6,B:3,C:0})[foreignPolicy];base=unit*qty;tariff=tariffUnit*qty;if(plan.resource==='food')food=qty;else luxury=qty;
 }else{const index=Number(plan.dealIndex),deal=r.trade.businessDeals[index];check(Number.isSafeInteger(index)&&deal,'商取引カードを選んでください');food=Number(deal.food||0);luxury=Number(deal.luxury||0);base=Number(deal.cost);destination=plan.destination;check(['regular','freeTrade'].includes(destination),'保管先が不正です');const policyTariff=foreignPolicy==='A'?Number(deal.tariffA):foreignPolicy==='B'?Number(deal.tariffB):0;tariff=destination==='regular'?policyTariff:0;r.trade.businessDeals.splice(index,1);}
 payCapitalist(cap,base+tariff);state.cash=Number(state.cash||0)+tariff;const foodKey=destination==='freeTrade'?'freeTradeFood':'food',luxuryKey=destination==='freeTrade'?'freeTradeLuxury':'luxury';cap[foodKey]=destination==='freeTrade'?Math.min(8,Number(cap[foodKey]||0)+food):Number(cap[foodKey]||0)+food;cap[luxuryKey]=destination==='freeTrade'?Math.min(12,Number(cap[luxuryKey]||0)+luxury):Number(cap[luxuryKey]||0)+luxury;return {records:validate(r),base,tariff,total:base+tariff,food,luxury,destination};
}
function applyCapitalistBuild(records,id,value,common,payment){const r=clone(records),d=companyDef(id);check(d?.class==='Capitalist'&&r.companies[id]?.status==='market','資本家の市場にある企業を選んでください');check(Object.entries(r.companies).filter(([companyId,c])=>companyDef(companyId)?.class==='Capitalist'&&c.status==='built').length<12,'資本家企業は12社までです');company(value,id);check(value.status==='built','設立後の企業状態が不正です');const occupied=value.slots.filter(x=>x.owner!=='empty'),automated=d.workers.length===0||d.tags?.includes('Automated');check(!occupied.length||occupied.length===value.slots.length,'設立時の労働者は全スロットへ同時に配置してください');check(!occupied.length||occupied.every(x=>x.committed),'設立時に配置する労働者は全員誓約中です');check(value.operating===((automated||occupied.length)?'yes':'no'),'設立直後の操業状態が不正です');const expected=clone(r.common.unemployed);for(let i=0;i<value.slots.length;i++){const slot=value.slots[i];if(slot.owner==='empty')continue;check(workerFits(d.workers[i],slot.owner,slot.skill,d.class),'スロットに配置できない労働者です');check(Number(expected?.[slot.owner]?.[slot.skill]||0)>0,'失業労働者が足りません');expected[slot.owner][slot.skill]--;}for(const owner of ['Working','Middle'])for(const skill of Object.keys(skills))check(Number(common?.unemployed?.[owner]?.[skill]||0)===Number(expected?.[owner]?.[skill]||0),'失業労働者の更新が一致しません');const capitalistCost=payment?Number(payment.capitalistCost):Number(d.cost),stateCost=payment?Number(payment.stateCost||0):0;check(Number.isSafeInteger(capitalistCost)&&capitalistCost>=0&&Number.isSafeInteger(stateCost)&&stateCost>=0&&capitalistCost+stateCost+Number(payment?.discount||0)===Number(d.cost),'設立費用の分担が不正です');payCapitalist(r.personal.Capitalist.values,capitalistCost);if(stateCost)payMandatory(r.personal.State.values,stateCost);r.companies[id]=clone(value);r.common=clone(common);return validate(r);}
function applyCapitalistAutomaBuild(records,plan,laborPolicy,bonusType){check(plan?.action==='BC','企業の設立計画が不正です');check((plan.bonusType||null)===(bonusType||null),'企業設立ボーナスがAIカードと一致しません');let r=clone(records);const builds=plan.builds||[plan];check(builds.length>0&&builds.length<=(bonusType==='doubleBuild'?2:1),'設立する企業数が不正です');for(const item of builds){const d=companyDef(item.companyId);check(d?.class==='Capitalist','企業の設立計画が不正です');const expectedState=bonusType==='halfBuild'&&['Food','Luxury'].includes(d.industry)?Math.floor(Number(d.cost||0)/2):0,discount=bonusType==='buildDiscount10'?Math.min(10,Number(d.cost)-expectedState):0;check(Number(item.stateCost||0)===expectedState&&Number(item.discount||0)===discount&&Number(item.capitalistCost)===Number(d.cost)-expectedState-discount,'設立費用のボーナスが不正です');const hasWage=Object.keys(d.wages||{}).length>0,wage=hasWage?({A:'L3',B:'L2',C:'L1'})[laborPolicy]:'unknown';check(item.wage===wage,'最低賃金の設定が不正です');const slots=clone(item.slots||[]),automated=d.workers.length===0||d.tags?.includes('Automated'),occupied=slots.filter(x=>x.owner!=='empty');check(slots.length===d.workers.length,'企業スロット数が不正です');check(Boolean(item.operating)===(automated||occupied.length===slots.length&&occupied.length>0),'操業状態が不正です');const common=clone(r.common);for(let i=0;i<slots.length;i++){const slot=slots[i];if(slot.owner==='empty')continue;check(workerFits(d.workers[i],slot.owner,slot.skill,d.class),'スロットに配置できない労働者です');check(slot.committed,'設立時の労働者は誓約中です');check(Number(common.unemployed?.[slot.owner]?.[slot.skill]||0)>0,'失業労働者が足りません');common.unemployed[slot.owner][slot.skill]--;}const value={status:'built',wage,operating:item.operating?'yes':'no',machinery:false,strike:false,note:'',slots};r=applyCapitalistBuild(r,d.id,value,common,{capitalistCost:Number(item.capitalistCost),stateCost:expectedState,discount});}for(const id of plan.marketAdds||[]){const d=companyDef(id);check(d?.class==='Capitalist'&&r.companies[id]?.status==='unbuilt','企業市場へ補充できないカードです');r.companies[id].status='market';}const available=Object.entries(r.companies).filter(([id,c])=>companyDef(id)?.class==='Capitalist'&&c.status==='unbuilt').length+(plan.marketAdds||[]).length,required=Math.min(Number(plan.marketDraw||0),available);check((plan.marketAdds||[]).length===required,'企業市場の補充枚数が不正です');if(plan.legitimacy&&r.participants.State==='human')r.personal.State.values.capitalistLegitimacy=Number(r.personal.State.values.capitalistLegitimacy||0)+Number(plan.legitimacy);return validate(r);}
function applyCapitalistSell(records,id,revenue=null){const r=clone(records),d=companyDef(id),c=r.companies[id];check(d?.class==='Capitalist'&&c?.status==='built','売却できる資本家企業ではありません');check(!c.slots.some(x=>x.committed),'誓約中の労働者がいる企業は売却できません');for(const slot of c.slots)if(['Working','Middle'].includes(slot.owner))r.common.unemployed[slot.owner][slot.skill]=Number(r.common.unemployed[slot.owner][slot.skill]||0)+1;r.personal.Capitalist.values.revenue=Number(r.personal.Capitalist.values.revenue||0)+Number(revenue==null?d.cost:revenue);r.companies[id]={...emptyCompany(d,'discarded'),wage:c.wage};return validate(r);}
