function marketCompanyCard(def,c){const resource=esc(({Influence:'影響力',...industries})[def.production.resource]||def.production.resource),machinery=Number(def.production?.machinery_bonus||0),automated=!def.workers?.length||def.tags?.includes('Automated');return `<button class="company-card market-card industry-${def.industry.toLowerCase()}" data-company="${def.id}"><span class="company-topline"><span>${industries[def.industry]}</span><span>費用 ${def.cost??0}</span></span><strong>${esc(companyName(def))}</strong><span class="company-stats">${automated?'自動化企業':`労働者スロット ${def.workers.length}`}</span><span class="company-workers">${automated?'<span class="worker-token automated">自動</span>':def.workers.map(marketWorker).join('')}</span><span class="company-output">生産 ${def.production.amount??'?'} ${resource}${machinery?` ／ 機械 +${machinery}`:''}</span></button>`;}
