function stateMarkup(r,s){const state=r.personal.State||{values:{},note:''},v=r.common.values||{},healthPrice={A:0,B:5,C:10}[s.positions[4]],educationPrice={A:0,B:5,C:10}[s.positions[5]];return `<section class="panel state-board"><div class="section-heading"><div><span class="eyebrow">STATE</span><h2>国家</h2></div><div class="treasury"><span>国庫</span><strong>${state.values.cash??'?'}</strong></div></div><div class="product-grid"><article><span>医療</span><strong>${v.health??'?'}</strong><small>価格 ${healthPrice}</small></article><article><span>教育</span><strong>${v.education??'?'}</strong><small>価格 ${educationPrice}</small></article><article><span>影響力</span><strong>${v.influence??'?'}</strong><small>価格 ${v.influencePrice??'?'}</small></article></div><p class="source">国家が供給するのは医療・教育・影響力です。医療は政策4、教育は政策5の現在位置から価格を表示します。</p></section><section class="panel"><details><summary>国家の数量を編集</summary><form id="stateForm"><div class="grid">${numeric('cash','国庫',state.values.cash)}${numeric('loans','貸付金',state.values.loans)}${numeric('health','公共医療',v.health)}${numeric('education','公共教育',v.education)}${numeric('influence','公共の影響力',v.influence)}${numeric('influencePrice','影響力単価',v.influencePrice)}</div><button type="submit">国家を保存</button><span class="draft-state"></span></form></details></section>`;}
function exportOfferRow(resource,offer={},index=0){const label=tradeResources[resource];return `<div class="trade-offer export-offer-line"><input type="hidden" data-trade-resource value="${resource}"><label><input data-trade-quantity aria-label="${label}${index+1}件目の数量" type="number" min="1" step="1" value="${offer.quantity??''}"><span>個</span></label><span class="export-arrow">→</span><label><input data-trade-revenue aria-label="${label}${index+1}件目の受取額" type="number" min="0" step="1" value="${offer.revenue??''}"><span>${vardisIcon}</span></label></div>`;}
