function tradeFormFields(value,dealCount){const trade=tradeData(value),deals=Array.from({length:dealCount},(_,i)=>trade.businessDeals[i]||{name:'',food:0,luxury:0,cost:0,tariffA:0,tariffB:0});return `<h3>輸出カード</h3><div class="export-offer-grid" data-export-offers>${Object.keys(tradeResources).map(resource=>exportOfferGroup(resource,trade.exportCard.offers)).join('')}</div><h3>商取引カード</h3>${deals.length?deals.map((deal,i)=>`<fieldset class="worker-slot" data-business-deal><legend>${i+1}枚目</legend><div class="grid"><label>食料<input data-deal-food type="number" min="0" step="1" value="${deal.food}"></label><label>ぜいたく品<input data-deal-luxury type="number" min="0" step="1" value="${deal.luxury}"></label><label>価格 ${vardisIcon}<input data-deal-cost type="number" min="0" step="1" value="${deal.cost}"></label></div><p class="setup-summary trade-tariff-summary">関税（自動）：政策6B <strong data-deal-tariff-b>${deal.tariffB??0}</strong>${vardisIcon}／政策6A <strong data-deal-tariff-a>${deal.tariffA??0}</strong>${vardisIcon}</p></fieldset>`).join(''):'<p class="muted">政策6Aのため、商取引カードはありません。</p>'}`;}
function updateTradeTariffs(form){for(const box of form.querySelectorAll('[data-business-deal]')){const total=Number(box.querySelector('[data-deal-food]').value||0)+Number(box.querySelector('[data-deal-luxury]').value||0);box.querySelector('[data-deal-tariff-b]').textContent=total;box.querySelector('[data-deal-tariff-a]').textContent=total*2;}}
