function importPrices(position){return position==='A'?{food:{base:10,tariff:10},luxury:{base:6,tariff:6}}:position==='B'?{food:{base:10,tariff:5},luxury:{base:6,tariff:3}}:{food:{base:10,tariff:0},luxury:{base:6,tariff:0}};}
function tradeMarkup(r,s){const trade=tradeData(r.trade),prices=importPrices(s.positions[6]),dealCount=({A:0,B:1,C:2})[s.positions[6]],offers=trade.exportCard.offers.map(x=>`<li>${tradeResources[x.resource]} ×${x.quantity}：${x.revenue}${vardisIcon}</li>`).join(''),deals=trade.businessDeals.map((x,i)=>`<li>${i+1}枚目：食料${x.food}・ぜいたく品${x.luxury}／本体${x.cost}${vardisIcon}・関税A ${x.tariffA}${vardisIcon}・B ${x.tariffB}${vardisIcon}</li>`).join('');return `<section class="panel"><span class="eyebrow">IMPORT AND EXPORT</span><h2>輸出入</h2><h3>海外市場からの輸入</h3><div class="product-grid"><article><span>食料</span><strong>${prices.food.base+prices.food.tariff}${vardisIcon}</strong><small>本体${prices.food.base}＋関税${prices.food.tariff}</small></article><article><span>ぜいたく品</span><strong>${prices.luxury.base+prices.luxury.tariff}${vardisIcon}</strong><small>本体${prices.luxury.base}＋関税${prices.luxury.tariff}</small></article></div><p class="source">海外市場に在庫はなく、購入できるのは食料とぜいたく品です。価格と関税は政策6${s.positions[6]}に連動します。</p><h3>輸出カード</h3><div class="setup-summary">${offers?`<ul>${offers}</ul>`:'輸出条件が未入力です。'}</div><h3>商取引カード</h3><div class="setup-summary">${deals?`<ul>${deals}</ul>`:`政策6${s.positions[6]}：${dealCount?`${dealCount}枚を入力してください`:'カードなし'}`}</div></section><section class="panel"><details><summary>輸出入カードを編集</summary><form id="tradeForm">${tradeFormFields(trade,dealCount)}<button type="submit">輸出入カードを保存</button><span class="draft-state"></span></form></details></section>`;}
function openPreparationTrade(value,positions,dealCount,onSave){document.getElementById('preparationTradeDialog')?.remove();const dialog=document.createElement('dialog');dialog.id='preparationTradeDialog';dialog.setAttribute('aria-labelledby','preparationTradeTitle');dialog.innerHTML=`<div class="dialog-heading"><span class="eyebrow">IMPORT AND EXPORT</span><h2 id="preparationTradeTitle">輸出入カードを記録</h2><p>新しい輸出カード1枚と、政策6${positions[6]}に従う商取引カード${dealCount}枚の内容を入力してください。</p></div><form id="preparationTradeForm">${tradeFormFields(value||blankTrade(),dealCount)}<p id="tradeDialogError" class="notice" hidden></p><div class="dialog-actions"><button type="button" id="preparationTradeCancel" class="quiet">戻る</button><button type="submit">カード内容を保存</button></div><span class="draft-state"></span></form>`;document.body.append(dialog);const form=dialog.querySelector('form');bindTradeForm(form,trade=>{dialog.close();dialog.remove();onSave(trade);},dealCount,true);dialog.querySelector('#preparationTradeCancel').onclick=()=>{dialog.close();dialog.remove();};dialog.addEventListener('cancel',e=>{e.preventDefault();dialog.close();dialog.remove();});dialog.showModal();}
